<script setup>defineProps({state:Object})</script><template><div v-if="state.error" role="alert" class="my-4 rounded-xl bg-red-50 text-red-800 p-4 text-xs">{{state.error}} <button class="underline ml-3" :disabled="state.busy" @click="state.load?.(state.page||0)">Thử lại</button></div><p v-if="state.busy" role="status" class="my-4 text-xs text-gray-500">Đang xử lý…</p><p v-if="state.notice" role="status" class="my-4 rounded-xl bg-emerald-50 text-emerald-800 p-4 text-xs">{{state.notice}}</p></template>